{
  "name": "rf_prepare_tx_path",
  "confidence": "medium",
  "docstring": "Prepares and validates the transmit RF path descriptor, bandwidth/rate context, and calibration settings, falling back to rf_set_band_config for invalid parameters.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "tx_ctx",
    "a2": "band_cfg",
    "v2": "bandwidth_or_path",
    "v5": "rate_index",
    "v6": "rate_table",
    "v7": "rate_entry",
    "v9": "tx_flags",
    "v13": "tx_flags",
    "v14": "bandwidth_entry",
    "v32": "tx_path_ptr",
    "v33": "bt_conn_state"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "transmit bandwidth/path index, valid range 0-3"
    },
    {
      "offset": 29,
      "meaning": "rate/MCS index; 0xff indicates unspecified rate"
    },
    {
      "offset": 30,
      "meaning": "transmit path flags; bits 0x08, 0x10, and 0x80 are interpreted specially"
    },
    {
      "offset": 44,
      "meaning": "selected TX path descriptor or function-pointer slot"
    },
    {
      "offset": 72,
      "meaning": "pointer to associated radio/TX context; subfields near 164/172 hold rate tables"
    }
  ]
}
